import {compareOffers,offerFields,validateOffers,notListed} from './offer-tools.mjs';
import {colMetros} from './offer-col.mjs';
const labels={company:'Company *',role:'Role',location:'Location *',baseSalary:'Annual base salary (USD) *',annualBonusTargetPct:'Target annual bonus (% of base)',annualBonus:'Annual bonus amount (USD; use amount OR percent)',signingBonus:'One-time signing bonus (USD)',relocation:'One-time relocation payment (USD)',equityTotalValue:'Total equity grant value (USD)',vestingYears:'Vesting years (default 4)',cliffYears:'Cliff years (0 if explicitly none)',retirementMatchPct:'Employer match rate (% of employee contributions)',retirementMatchCapPct:'Employee contribution cap (% of base)',ptoDays:'Annual PTO days',remotePolicy:'Remote / hybrid policy',startDate:'Start date',expiresOn:'Offer expiry date',notes:'Notes / your priorities'};
const money=value=>typeof value==='number'?value.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}):value;
export function createOffersPanel({document,panel,store,discuss,notify=()=>{},now=()=>new Date()}){
 let editing=null,draft=null;
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 const button=(text,fn)=>{const b=el('button',text,'chip');b.type='button';b.addEventListener('click',fn);return b;};
 const run=fn=>{try{fn();render();}catch(e){notify(e.message);}};
 function form(){
  const f=el('form',undefined,'workspace-card manual-application-form');f.noValidate=true;f.append(el('h2',editing?'Edit offer':'Add an offer'),el('p','Enter disclosed amounts only. Leave unknown terms blank; enter 0 only when confirmed absent. Use annual USD amounts.','small-note'));
  const grid=el('div',undefined,'manual-application-grid'),inputs={};
  for(const name of offerFields){const label=el('label'),input=el(name==='notes'?'textarea':'input');input.name=name;input.id='offer-'+name;label.append(el('span',labels[name]));input.setAttribute('aria-label',labels[name]);
   const number=/Salary|Bonus|relocation|Value|Years|Pct|Days/.test(name);if(name!=='notes')input.type=['startDate','expiresOn'].includes(name)?'date':number?'number':'text';if(number){input.min='0';input.step='any';}input.maxLength=name==='notes'?4000:240;input.required=['company','baseSalary','location'].includes(name);input.value=draft?.[name]===notListed?'':String(draft?.[name]??'');input.addEventListener('input',()=>{draft[name]=input.value;error.textContent='';});if(name==='location')input.setAttribute('list','offer-metros');if(name==='vestingYears')input.placeholder='4 when not supplied';label.append(input);grid.append(label);inputs[name]=input;
  }
  const options=el('datalist');options.id='offer-metros';for(const metro of colMetros){const option=el('option');option.value=metro.name;options.append(option);}f.append(grid,options,el('p','Retirement example: a 50% match up to employee contributions of 6% of base yields an employer contribution of 3% of base, assuming you contribute the full cap. Verify the actual plan.','small-note'));
  const error=el('p','','manual-form-error');error.setAttribute('role','alert');f.append(error);const actions=el('div',undefined,'workspace-actions'),save=el('button','Save offer','manual-submit');save.type='submit';actions.append(save,button('Cancel',()=>{draft=null;editing=null;render();}));f.append(actions);
  f.addEventListener('submit',event=>{event.preventDefault();try{const values=Object.fromEntries(Object.entries(inputs).map(([key,input])=>[key,input.value.trim()]));for(const key of ['company','baseSalary','location'])if(values[key]===''){inputs[key].focus();throw Error('Enter '+labels[key].replace(' *','')+'.');}store.saveOffer(validateOffers([values])[0],editing);draft=null;editing=null;render();panel.scrollTop=0;notify('Offer saved in this browser.');}catch(e){error.textContent=e.message;}});return f;
 }
 function render(){
  const saved=store.read().offers||[];panel.replaceChildren(el('h1','Your job offers'),el('p','Compare up to four offers using disclosed terms. Calculations work without an API key. Discuss your priorities with the coach when AI is connected.','workspace-intro'));
  const add=button('Add an offer',()=>{if(saved.length>=4)return notify('You can compare up to 4 offers. Edit or delete one first.');editing=null;draft={};render();panel.querySelector?.('#offer-company')?.focus();});add.disabled=saved.length>=4;panel.append(add);if(draft)panel.append(form());
  if(!saved.length){panel.append(el('div','No offers yet. Add an offer above; no API key is needed.','workspace-empty'));return;}
  const offers=validateOffers(saved.map(({id,...o})=>o)),report=compareOffers(offers,{now:now()});
  const wrap=el('div',undefined,'offer-table-wrap'),table=el('table',undefined,'offer-table'),caption=el('caption','Offer comparison · USD, before tax');table.append(caption);const head=el('thead'),hr=el('tr');for(const title of ['Company / role','Year one','Four years','COL index','COL-adjusted year one','Verify']){const th=el('th',title);th.setAttribute('scope','col');hr.append(th);}head.append(hr);table.append(head);const body=el('tbody');
  for(const o of report.offers){const row=el('tr');for(const value of [o.company+' · '+o.role,money(o.yearOneTotal)+(o.yearOneTotal===notListed?' (known subtotal '+money(o.knownYearOneTotal)+')':''),money(o.fourYearTotal)+(o.fourYearTotal===notListed?' (known subtotal '+money(o.knownFourYearTotal)+')':''),String(o.costOfLivingIndex),money(o.colAdjustedYearOne),o.flags.join(' ')])row.append(el('td',value));body.append(row);}table.append(body);wrap.append(table);panel.append(wrap);
  for(const [i,o]of report.offers.entries()){
   const card=el('article',undefined,'workspace-card');card.append(el('h2',o.company),el('p','COL-adjusted base: '+money(o.colAdjustedBase)),el('p','Not listed: '+(o.missing.join(', ')||'None')));
   const details=el('details');details.append(el('summary','Calculation assumptions and supplied terms'));for(const value of o.assumptions)details.append(el('p',value));for(const name of offerFields)details.append(el('p',labels[name].replace(' *','')+': '+String(o[name])));card.append(details);
   const actions=el('div',undefined,'workspace-actions');actions.append(button('Edit '+o.company,()=>{editing=saved[i].id;draft={...offers[i]};render();}),button('Delete '+o.company,()=>run(()=>{store.remove('offers',saved[i].id);if(editing===saved[i].id){editing=null;draft=null;}})));card.append(actions);panel.append(card);
  }
  const ranking=el('section',undefined,'workspace-card');ranking.append(el('h2','Numerical comparison'),el('p',report.comparison.basis));for(const [key,title]of [['byYearOne','Year one'],['byColAdjustedYearOne','COL-adjusted year one']]){ranking.append(el('h3',title));const rows=report.comparison[key];if(!rows.length)ranking.append(el('p','No complete packages to rank yet. Confirm missing amounts before comparing totals.'));for(const row of rows)ranking.append(el('p',row.rank+'. '+row.company+': '+money(row.value)+' · difference from leader '+money(row.differenceDollars)+' / '+(typeof row.differencePercent==='number'?row.differencePercent+'%':notListed)));}panel.append(ranking);
  panel.append(button('Discuss with coach',()=>discuss(offers)),el('p',report.notice,'small-note'));const source=el('a','BEA COL snapshot: '+report.colSource.dataYear+' · released '+report.colSource.released+' · checked '+report.colSource.asOf);source.href=report.colSource.documentation;source.target='_blank';source.rel='noopener noreferrer';panel.append(source,el('p','Remote (US) uses national reference 100; unknown locations receive no adjustment. Offers stay in this browser; no account sync. Only Discuss with coach sends them to AI.','small-note'));
 }
 return {render};
}
